const WINDOW_DAYS = 3;  // nudge when a festival is 0-3 days away
const forChat = (() => { try { return String($('Start').first().json.for_chat || ''); } catch (e) { return ''; } })();
const FORCE = !!forChat; // demo command: only this shop, even if it already posted for the festival

const FESTIVALS = [
  ['2026-11-08', 'Kali Puja / Diwali', 'কালীপুজো / দীপাবলি', 'sweets, diyas, lights, gift boxes'],
  ['2026-11-11', 'Bhai Phonta', 'ভাইফোঁটা', 'sweets, gift boxes, phonta thali, sarees, shirts'],
  ['2026-11-14', "Children's Day", 'শিশু দিবস', 'chocolates, cakes, toys, stationery'],
  ['2026-11-15', 'Chhath Puja', 'ছট পুজো', 'thekua, fruits, sugarcane, puja items'],
  ['2026-11-18', 'Jagaddhatri Puja', 'জগদ্ধাত্রী পুজো', 'sweets, new clothes, lights'],
  ['2026-11-24', 'Guru Nanak Jayanti', 'গুরু নানক জয়ন্তী', 'sweets'],
  ['2026-12-25', 'Christmas', 'বড়দিন', 'cakes, plum cake, gifts, decorations'],
  ['2027-01-01', 'New Year', 'ইংরেজি নববর্ষ', 'cakes, gifts, party orders'],
  ['2027-01-26', 'Republic Day', 'প্রজাতন্ত্র দিবস', 'tricolour sweets, school supplies'],
  ['2027-02-14', "Valentine's Day", 'ভ্যালেন্টাইনস ডে', 'cakes, chocolates, flowers, gifts'],
];

const todayIST = new Date(Date.now() + 5.5 * 3600 * 1000).toISOString().slice(0, 10);
const t0 = Date.parse(todayIST);
const upcoming = FESTIVALS
  .map(([date, en, bn, products]) => ({ date, en, bn, products, in_days: Math.round((Date.parse(date) - t0) / 86400000) }))
  .filter(f => f.in_days >= 0 && f.in_days <= 30);
const inWindow = upcoming.filter(f => f.in_days <= WINDOW_DAYS);
const sameFest = (a, b) => {
  const parts = s => String(s || '').toLowerCase().split('/').map(x => x.trim()).filter(Boolean);
  return parts(a).some(x => parts(b).some(y => x.includes(y) || y.includes(x)));
};

const shops = $('Get shops').all().map(i => i.json).filter(s => s.chat_id && s.chat_id !== 'PENDING');
const posts = $('Get recent posts').all().map(i => i.json).filter(p => p.post_id);

const out = [];
for (const shop of shops) {
  if (FORCE && String(shop.chat_id) !== forChat) continue;
  const mine = posts.filter(p => String(p.chat_id) === String(shop.chat_id));
  const alreadyPosted = f => mine.some(p => p.status === 'posted' && sameFest(p.festival, f.en));
  const fest = FORCE ? (inWindow[0] || upcoming[0]) : inWindow.find(f => !alreadyPosted(f));
  if (!fest) continue;
  out.push({ json: { chat_id: shop.chat_id, shop, festival: fest, recent_products: mine.slice(-5).map(p => p.product).filter(Boolean) } });
}
return out;

const MAX_TOKENS = 500;
const lang = ($json.shop.languages === 'bn' || $json.shop.languages === 'en') ? $json.shop.languages : 'mixed';
const LANG_RULE = { bn: 'Write in natural West Bengal Bengali only.', en: 'Write in simple, friendly Indian English only.', mixed: 'Write in Bengali, with one short English line at the end.' }[lang];
const SYSTEM = `You write a short, friendly Telegram nudge from a small business's marketing assistant (Dukaan Digital) to the owner. ${LANG_RULE}
- Mention the festival and its date (as given), and how many days are left.
- Suggest ONE specific product or service idea that fits both the festival and this business type (use the festival's typical products and the shop's recent products). If the festival does not fit this business at all, suggest a simple greeting post instead.
- Ask the owner to send a photo (and a voice note with the price).
- Max 4 lines, max 2 emojis. No invented offers or prices.

Return ONLY valid JSON:
{ "message": "the Telegram text" }`;
const facts = {
  shop: { name_bn: $json.shop.shop_name_bn, name_en: $json.shop.shop_name_en, type: $json.shop.shop_type },
  festival: $json.festival,
  recent_products: $json.recent_products,
};
const user = JSON.stringify(facts, null, 2) + '\nReturn the JSON now.';
return { json: { agent: 'nudge', chat_id: $json.chat_id, system: SYSTEM, user, max_tokens: MAX_TOKENS } };

const REQUIRED = ['message'];
function rawText(j) {
  if (typeof j.merged_response === 'string') return j.merged_response;
  if (typeof j.content === 'string') return j.content;
  if (j.message && typeof j.message.content === 'string') return j.message.content;
  if (Array.isArray(j.content)) return j.content.map(c => c.text || '').join('');
  if (j.content && Array.isArray(j.content.parts)) return j.content.parts.map(p => p.text || '').join('');
  if (Array.isArray(j.candidates)) return (((j.candidates[0] || {}).content || {}).parts || []).map(p => p.text || '').join('');
  if (typeof j.output === 'string') return j.output;
  if (typeof j.text === 'string') return j.text;
  return JSON.stringify(j);
}
function extract(s) { s = s.replace(/```(?:json)?/gi, '').trim(); const a = s.indexOf('{'), b = s.lastIndexOf('}'); if (a === -1 || b <= a) throw new Error('no JSON object found'); return JSON.parse(s.slice(a, b + 1)); }
return $input.all().map((item, i) => {
  const raw = rawText(item.json || {});
  try { const data = extract(raw); const missing = REQUIRED.filter(k => !(k in data));
    if (missing.length) return { json: { ok: false, error: 'missing keys: ' + missing.join(', '), raw: raw.slice(0, 500) }, pairedItem: i };
    return { json: { ok: true, ...data }, pairedItem: i };
  } catch (e) { return { json: { ok: false, error: String(e.message || e), raw: raw.slice(0, 500) }, pairedItem: i }; }
});

const forChat = (() => { try { return String($('Start').first().json.for_chat || ''); } catch (e) { return ''; } })();
const rows = $input.all().map(i => i.json).filter(r => r && r.post_id && r.status === 'posted' && (!forChat || String(r.chat_id) === forChat));
const num = v => Number(v) || 0;
const eng = r => num(r.reactions) + 2 * num(r.comments) + 3 * num(r.shares);
const avg = a => (a.length ? Math.round(a.reduce((s, r) => s + eng(r), 0) / a.length) : null);

function groupBy(key) {
  const g = {};
  for (const r of rows) { const k = r[key] || 'none'; (g[k] = g[k] || []).push(r); }
  return Object.fromEntries(Object.entries(g).map(([k, a]) => [k, { posts: a.length, avg_engagement: avg(a) }]));
}

const festival = rows.filter(r => r.angle === 'festival');
const nonFestival = rows.filter(r => r.angle !== 'festival');
const withPrice = rows.filter(r => r.has_price_on_poster === 'yes');
const noPrice = rows.filter(r => r.has_price_on_poster !== 'yes');
const ratio = (a, b) => (a && b ? Math.round((a / b) * 10) / 10 : null);
const best = [...rows].sort((a, b) => eng(b) - eng(a))[0] || null;

const stats = {
  posts_analysed: rows.length,
  seeded_demo_posts: rows.filter(r => r.source === 'seeded_demo').length,
  live_posts: rows.filter(r => r.source !== 'seeded_demo').length,
  avg_engagement_all: avg(rows),
  by_angle: groupBy('angle'),
  festival_vs_other: { festival: avg(festival), other: avg(nonFestival), ratio: ratio(avg(festival), avg(nonFestival)) },
  price_on_poster: { with_price: avg(withPrice), without_price: avg(noPrice), ratio: ratio(avg(withPrice), avg(noPrice)) },
  best_post: best ? { product: best.product, angle: best.angle, festival: best.festival || null, engagement: eng(best), date: String(best.created_at).slice(0, 10) } : null,
  engagement_formula: 'reactions + 2*comments + 3*shares',
};

return [{ json: { stats } }];

